def handle(app, svc):
    """Handler for the Redfern partner (ticket KF-20).

    Redfern runs the network's current API version (v2). The service call
    svc.apply(app) returns:
        {"api_version": 2, "result": {"outcome": "approved"|"declined"|"manual_review",
                                      "credit_limit": int}}
    We translate that into the internal action:
        approved       -> issue        (limit = credit_limit)
        declined       -> decline      (limit = 0)
        manual_review  -> queue_review (limit = 0)
    """
    resp = svc.apply(app)

    # API v2: decision is nested under "result".
    if isinstance(resp, dict) and resp.get("api_version", 2) == 2 and isinstance(resp.get("result"), dict):
        result = resp["result"]
        outcome = result.get("outcome")
        limit = result.get("credit_limit", 0) or 0
    else:
        # Defensive fallback to the API v1 shape.
        decision = resp.get("decision") if isinstance(resp, dict) else None
        limit = resp.get("limit", 0) or 0 if isinstance(resp, dict) else 0
        outcome = {"approve": "approved", "decline": "declined"}.get(decision, "manual_review")

    if outcome == "approved":
        return {"action": "issue", "limit": int(limit)}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    return {"action": "queue_review", "limit": 0}
